const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '../..');
const read = (file) => fs.readFileSync(path.join(root, file), 'utf8');
const ok = (v, m) => { if (!v) throw new Error(m); };
const auth = read('assets/js/core/auth.js');
const portal = read('assets/js/core/portal.js');
const map = read('assets/js/features/mapa/app.js');
const api = read('functions/surveyor-api/src/main.js');
ok(auth.includes('layers: 7 * 24 * 60 * 60_000'), 'catálogo deve ficar em cache por 7 dias no cliente');
ok(auth.includes('notices: 30 * 60_000'), 'avisos devem usar cache de 30 minutos');
ok(auth.includes("PERSISTENT_API_CACHE_KEY = 'georural-api-persistent-cache-v1'"), 'cache persistente local ausente');
ok(auth.includes("normalized === '/api/layers/catalog'"), 'catálogo deve usar cache persistente');
ok(portal.includes('NOTICE_POLL_MS = 30 * 60_000'), 'poll de avisos deve ser 30 min');
ok(portal.includes('if (document.hidden && !force) return;'), 'aba oculta não deve consultar avisos');
ok(map.includes('CATALOG_RELOAD_PERIODIC_MS = 7 * 24 * 60 * 60_000'), 'catálogo não deve forçar releitura horária');
ok(api.includes('SYSTEM_NOTICES_CACHE_TTL_MS = 30 * 60 * 1000'), 'cache server-side de avisos ausente');
ok(api.includes('PUBLIC_LAYER_CATALOG_CACHE_TTL_MS = 30 * 60 * 1000'), 'cache server-side de catálogo ausente');
ok(api.includes('publicLayerCatalogBaseCache = { at: Date.now(), groups, storedLayers }'), 'catálogo base deve ser reaproveitado na Function');
console.log('PASS: hotfix de escala reduz polling e leituras repetidas para cenário de 100+ usuários.');
